// WF-HEALTH — ferme le « vert à vide » : alerte si la file sociale est affamée.
// (a) aucune ligne passée `publié` depuis 72 h ; (b) moins de 7 jours de `validé` à venir ;
// (c) des `prêt_à_valider` dont la date prévue est dépassée ; (d) des `échec` depuis hier ;
// (e) des `image_needed` ; (f) des `rédigé` sans visuel depuis plus de 24 h.
const cfg = {};
for (const r of $('Config — aplatir').all()) { if (r.json.Cle) cfg[r.json.Cle] = r.json.Valeur; }
const seen = new Set();
const rows = $input.all().map(i => i.json).filter(r => r && r.Status && !seen.has(r.id) && seen.add(r.id));
const now = Date.now(), H = 3600 * 1000, D = 24 * H;
const t = (v) => { if (!v) return NaN; const x = new Date(String(v).replace(' ', 'T')).getTime(); return x; };
const fmt = (ms) => new Date(ms).toLocaleString('fr-FR', { timeZone: 'Africa/Dakar', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const publies = rows.filter(r => r.Status === 'publié');
const lastPub = Math.max(-Infinity, ...publies.map(r => t(r.UpdatedAt)).filter(Number.isFinite));
const valides = rows.filter(r => r.Status === 'validé');
const validesAVenir = valides.filter(r => t(r.Date_Publication_Prevue) >= now);
const horizon = Math.max(-Infinity, ...validesAVenir.map(r => t(r.Date_Publication_Prevue)));
const perimes = rows.filter(r => r.Status === 'prêt_à_valider' && Number.isFinite(t(r.Date_Publication_Prevue)) && t(r.Date_Publication_Prevue) < now);
const alertes = [];
if (!(lastPub > now - 72 * H)) alertes.push(`• Rien de publié depuis 72 h (dernier passage « publié » : ${Number.isFinite(lastPub) ? fmt(lastPub) + ', il y a ' + Math.floor((now - lastPub) / D) + ' j' : 'aucun'}).`);
const joursCouverts = Number.isFinite(horizon) ? (horizon - now) / D : 0;
if (joursCouverts < 7) alertes.push(`• File « validé » trop courte : ${validesAVenir.length} post(s) à venir, ${joursCouverts.toFixed(1)} j couverts (objectif : 7 j).`);
const echecs = rows.filter(r => r.Status === 'échec' && t(r.UpdatedAt) > now - 26 * H);
if (echecs.length) alertes.push(`• ${echecs.length} post(s) passé(s) en « échec » depuis hier (Id ${echecs.map(r => r.id).join(', ')}). Motif dans le champ Erreurs.`);
const sansVisuel = rows.filter(r => r.Status === 'image_needed');
if (sansVisuel.length) alertes.push(`• ${sansVisuel.length} post(s) bloqué(s) en « image_needed » (rendu raté ou visuel humain attendu) : Id ${sansVisuel.map(r => r.id).join(', ')}.`);
const rendusEnRetard = rows.filter(r => r.Status === 'rédigé' && t(r.UpdatedAt) < now - 24 * H);
if (rendusEnRetard.length) alertes.push(`• ${rendusEnRetard.length} post(s) « rédigé » attendent leur visuel depuis plus de 24 h : le rendu (WF-SOCIAL-04) est peut-être en panne.`);
if (perimes.length) alertes.push(`• ${perimes.length} post(s) « prêt_à_valider » dont la date est passée (le plus ancien : ${fmt(Math.min(...perimes.map(r => t(r.Date_Publication_Prevue))))}). À re-dater ou rejeter.`);
console.log('WF-HEALTH', JSON.stringify({ lignes: rows.length, publies: publies.length, valides: valides.length, validesAVenir: validesAVenir.length, perimes: perimes.length, lastPub: Number.isFinite(lastPub) ? new Date(lastPub).toISOString() : null, alertes: alertes.length }));
if (!alertes.length) return [];
const text = `🟠 Santé de la file sociale\n\n${alertes.join('\n')}\n\nFile NocoDB : Contenus. Vérifié le ${fmt(now)}.`;
return [{ json: { token: cfg.TELEGRAM_BOT_TOKEN, body: { chat_id: cfg.TELEGRAM_CHAT_ID, text, disable_web_page_preview: true }, resume: { lignes: rows.length, alertes: alertes.length, perimes: perimes.length, validesAVenir: validesAVenir.length, lastPub: Number.isFinite(lastPub) ? new Date(lastPub).toISOString() : null } } }];
